------------------
---- MONITORS ----
------------------

-- See https://wiki.hypr.land/Configuring/Basics/Monitors/
-- Mirrors the xrandr layout from dwm's autostart.sh:
-- DVI-D (1366x768, rotated left) sits left of HDMI-A (1920x1080, main).
hl.monitor({
    output    = "DVI-D-1",
    mode      = "1366x768@59.79",
    position  = "0x0",
    scale     = 1,
    transform = 1, -- 90°, matches `xrandr --rotate left` (3 came out upside down)
})

hl.monitor({
    output   = "HDMI-A-1",
    mode     = "1920x1080@60",
    position = "768x0", -- right of the rotated DVI-D (768px wide)
    scale    = 1,
})

-- Fallback for anything else plugged in
hl.monitor({
    output   = "",
    mode     = "preferred",
    position = "auto",
    scale    = "auto",
})


---------------------
---- MY PROGRAMS ----
---------------------

-- Set programs that you use
local terminal    = "kitty"
local fileManager = "kitty nnn"
local menu        = "hyprlauncher"

-- Workspace names, shared by both monitors, and each monitor's first ID - 1
local wsNames  = { "term", "code", "web", "chat", "misc" }
local wsOffset = { ["HDMI-A-1"] = 0, ["DVI-D-1"] = #wsNames }


-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
-- hl.on("hyprland.start", function () 
--   hl.exec_cmd(terminal)
--   hl.exec_cmd("nm-applet")
--   hl.exec_cmd("waybar & hyprpaper & firefox")
-- end)

-- No systemd user session here, so PipeWire has to be started by hand.
-- WirePlumber and pipewire-pulse exit if the PipeWire socket isn't up yet,
-- so wait for it before launching them.
hl.on("hyprland.start", function ()
    hl.exec_cmd([[
        pgrep -x pipewire >/dev/null || pipewire &
        for _ in $(seq 50); do [ -S "$XDG_RUNTIME_DIR/pipewire-0" ] && break; sleep 0.1; done
        pgrep -x wireplumber >/dev/null || wireplumber &
        pgrep -x pipewire-pulse >/dev/null || pipewire-pulse &
    ]])
end)

-- Wallpapers (config in hyprpaper.conf)
hl.on("hyprland.start", function ()
    hl.exec_cmd("pgrep -x hyprpaper >/dev/null || hyprpaper")
end)


