---------------------
---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER" -- dwm MODKEY (Mod4Mask)

-- Mirrors the keys[] / buttons[] tables in ~/Repos/dwm/config.h.

-- Programs
hl.bind(mainMod .. " + D",              hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + Return",         hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + SHIFT + Return", hl.dsp.exec_cmd(terminal .. " tmux"))
hl.bind("Print", hl.dsp.exec_cmd("mkdir -p ~/Pictures && grim ~/Pictures/screenshot-$(date +%Y%m%d-%H%M%S).png"))

-- Stack focus (focusstack), works in both master and monocle
hl.bind(mainMod .. " + J", hl.dsp.layout("cyclenext"))
hl.bind(mainMod .. " + K", hl.dsp.layout("cycleprev"))

-- Master count (incnmaster) and size (setmfact)
hl.bind(mainMod .. " + SHIFT + I", hl.dsp.layout("addmaster"))
hl.bind(mainMod .. " + SHIFT + D", hl.dsp.layout("removemaster"))
hl.bind(mainMod .. " + H",         hl.dsp.layout("mfact -0.05"), { repeating = true })
hl.bind(mainMod .. " + L",         hl.dsp.layout("mfact +0.05"), { repeating = true })

-- Previous workspace (view {0})
hl.bind(mainMod .. " + Tab", hl.dsp.focus({ workspace = "previous" }))

-- Kill client
hl.bind(mainMod .. " + SHIFT + Q", hl.dsp.window.close())

-- Layouts (setlayout): T tile, M monocle, Space back to the previous one.
-- Unlike dwm this is global rather than per monitor.
local prevLayout = "master"
local function setLayout(layout)
    local current = hl.get_config("general.layout")
    if layout ~= current then
        prevLayout = current
        hl.config({ general = { layout = layout } })
    end
end
hl.bind(mainMod .. " + T",     function() setLayout("master") end)
hl.bind(mainMod .. " + M",     function() setLayout("monocle") end)
hl.bind(mainMod .. " + space", function() setLayout(prevLayout) end)

-- Toggle floating
hl.bind(mainMod .. " + SHIFT + space", hl.dsp.window.float({ action = "toggle" }))

-- Monitors (focusmon / tagmon)
hl.bind(mainMod .. " + comma",          hl.dsp.focus({ monitor = "-1" }))
hl.bind(mainMod .. " + period",         hl.dsp.focus({ monitor = "+1" }))
hl.bind(mainMod .. " + SHIFT + comma",  hl.dsp.window.move({ monitor = "-1" }))
hl.bind(mainMod .. " + SHIFT + period", hl.dsp.window.move({ monitor = "+1" }))

-- Tags 1-5 (view / tag) on the focused monitor, like dwm's per-monitor tags.
-- Like dwm's tag, moving a window doesn't follow it.
local function wsOnFocusedMonitor(slot)
    local monitor = hl.get_active_monitor()
    return (monitor and wsOffset[monitor.name] or 0) + slot
end
for slot = 1, #wsNames do
    hl.bind(mainMod .. " + " .. slot, function()
        hl.dispatch(hl.dsp.focus({ workspace = wsOnFocusedMonitor(slot) }))
    end)
    hl.bind(mainMod .. " + SHIFT + " .. slot, function()
        hl.dispatch(hl.dsp.window.move({ workspace = wsOnFocusedMonitor(slot), follow = false }))
    end)
end

-- Quit
hl.bind(mainMod .. " + F4", hl.dsp.exit())

-- Mouse (buttons[]): move, toggle floating, resize
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:274", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Extras with no dwm counterpart (none clash with the binds above)
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + R", hl.dsp.exec_cmd("hyprctl reload"))

hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

hl.bind(mainMod .. " + S",         hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }))

hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "m+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "m-1" }))

-- Laptop multimedia keys for volume and LCD brightness
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      { locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),     { locked = true, repeating = true })
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),   { locked = true, repeating = true })
hl.bind("XF86MonBrightnessUp",  hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%+"),                  { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown",hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%-"),                  { locked = true, repeating = true })

-- Requires playerctl
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true })


--------------------------------
---- WINDOWS AND WORKSPACES ----
--------------------------------

-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

-- Per-monitor tags like dwm: each monitor owns five workspaces with the same
-- names. HDMI-A-1 has IDs 1-5, DVI-D-1 has 6-10 (see wsOffset in MY PROGRAMS).
for monitor, offset in pairs(wsOffset) do
    for slot, name in ipairs(wsNames) do
        hl.workspace_rule({
            workspace    = tostring(offset + slot),
            default_name = name,
            monitor      = monitor,
            default      = slot == 1,
            persistent   = true,
        })
    end
end

-- dwm rules[]
hl.window_rule({
    name  = "gimp-float",
    match = { class = "^[Gg]imp" },
    float = true,
})
hl.window_rule({
    -- "web" on the main monitor, without switching to it
    name      = "firefox-web",
    match     = { class = "^[Ff]irefox$" },
    workspace = wsOffset["HDMI-A-1"] + 3 .. " silent",
})

-- picom opacity-exclude
hl.window_rule({
    name    = "firefox-opaque",
    match   = { class = "^([Ff]irefox|firefox-esr|Firefox-esr|Navigator)$" },
    opacity = "1.0 override 1.0 override",
})

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

